That is, machine $i$ computes a partial gradient mapping \cite{Nesterov13} {w.

The composite minimization problem
\begin{align}\label{com_min}
\min_{\mathbf{x}\in \mathds{R}^d}~ f(\mathbf{x}) + g(\mathbf{x})
\end{align}
has drawn a lot of recent attention due to its ubiquity in machine learning and statistical applications.
Typically, the first term 
\begin{align}\label{finitesum}
f(\mathbf{x}) := \frac{1}{n}\sum_{i=1}^n f_i(\mathbf{x})
\end{align}

The Frech\'et subdifferential $\hat\partial h$ of $h$ at $\mathbf{x}\in\mathop{\mathrm{dom}} h$ is the set of $\mathbf{u}$ such that
\begin{align}
\liminf_{\mathbf{z}\neq\mathbf{x}, \mathbf{z}\to\mathbf{x}} \frac{h(\mathbf{z}) - h(\mathbf{x}) - \mathbf{u}^\top(\mathbf{z}-\mathbf{x})}{\|\mathbf{z}-\mathbf{x}\|} \geq 0,
\end{align}
while the (limiting) subdifferential $\partial h$ at $\mathbf{x}\in\mathop{\mathrm{dom}} h$ is the ``closure'' of $\hat\partial h$:
\begin{align}
\{ \mathbf{u}: \exists \mathbf{x}^k \to \mathbf{x}, h(\mathbf{x}^k) \to h(\mathbf{x}), \mathbf{u}^k \in \hat{\partial} h(\mathbf{x}^k), \mathbf{u}^k \to \mathbf{u} \}.
\end{align}
The critical points of $h$ are $\mathop{\mathrm{crit}} h := \{ \mathbf{x}: \mathbf{0}\in\partial h(\mathbf{x}) \}$. 
\end{definition}

When $h$ is continuously differentiable or convex, the subdifferential $\partial h$ and the set of critical points $\mathop{\mathrm{crit}} h$ coincide with the usual notions. For a closed function $h$, its subdifferential is either nonempty at any point in its domain or the subgradient diverges to some ``direction'' \cite[Corollary 8.10]{vari_ana}.
\begin{definition}[Distance and projection]\label{def: distance}
The distance function {w.r.t.}\xspace a closed set $\Omega \subseteq \mathds{R}^d$ is defined as:
\begin{align}

\mathrm{dist}_{\Omega}(\mathbf{x}) := \min_{\mathbf{y}\in\Omega} \|\mathbf{y}-\mathbf{x}\|,  
\end{align}

while the metric projection onto $\Omega$ is defined  as:
\begin{align}
\proj{\Omega}(\mathbf{x}) := \mathop{\mathrm{argmin}}_{\mathbf{y}\in\Omega} \|\mathbf{y}-\mathbf{x}\|,
\end{align}

The proximal map of a closed and proper function $h$ is (with parameter $\eta > 0$):
\begin{align}

\prox{h}(\mathbf{x}) := \mathop{\mathrm{argmin}}_{\mathbf{z}\in \mathds{R}^d} h(\mathbf{z}) + \tfrac{1}{2\eta}\|\mathbf{z} - \mathbf{x}\|^2.
\end{align}

For convex functions, the proximal map is nonexpansive:
\begin{align}
\label{eq:ne}
\forall \mathbf{x}, \forall \mathbf{y}, ~ \|\prox{h}(\mathbf{x}) - \prox{h}(\mathbf{y}) \| \leq \|\mathbf{x} - \mathbf{y}\|,
\end{align}
while for nonconvex functions this may not hold everywhere.

The proximal map is the key component of the proximal gradient algorithm \cite{FukushimaMine81} ({a.k.a.}\xspace forward-backward splitting):
\begin{align}
\label{eq:pg}
\forall\,t = 0, 1, \ldots, \quad \mathbf{x}(t+1) = \prox[\eta]{g}\big(\mathbf{x}(t) - \eta \nabla f(\mathbf{x}(t))\big),
\end{align}
where $\nabla f$ is the (sub)gradient of $f$, and $\eta$ is a suitable step size (that may  change with $t$). It is known that when $f$ is convex with $L$-Lipschitz continuous gradient  and $0 < \eta < 2/L$, then $F_t := f(\mathbf{x}(t))+g(\mathbf{x}(t))$ converges to the minimum at the rate $O(1/t)$ and $\mathbf{x}(t)$ converges to some minimizer $\mathbf{x}^*$. Accelerated versions \cite{FISTA,Nesterov13} where $F_t$ converges at the faster rate $O(1/t^2)$ are also well-known. Recently, \cite{prox_alter_linear} proved that $\mathbf{x}(t)$ converges to a critical point even for nonconvex $f$ and nonconvex and nonsmooth $g$ as long as together they satisfy a certain K\L\xspace inequality.






\section{Formulation of $\textsf{m-PAPG}\xspace$}\label{sec: models}
Recall the composite minimization problem:
\begin{align}
\label{compmin}

\min_{\mathbf{x}\in\mathds{R}^d} F(\mathbf{x}), \quad \mbox{ where } \quad F(\mathbf{x}) = f(\mathbf{x}) + g(\mathbf{x}). \tag{P}
\end{align}

