	It is clear from \Cref{thm:limitcon} that $\{\mathbf{x}(t)\}$ and $\{\mathbf{x}^i(t)\}, i=1, \ldots, p$, share the same set of limit points, and we need to show that any limit point of $\{\mathbf{x}(t)\}$ is also a critical point of $F$.

	Let $\mathbf{x}^*$ be a limit point of $\{\mathbf{x}(t)\}$. By \Cref{def:sub} it suffices to exhibit a sequence $\mathbf{x}(k)$ satisfying\footnote{Technically, from \Cref{def:sub} we should have the Frech\'et subdifferential $\hat{\partial} F$ in \cref{crit_want}, however, a standard argument allows us to use the more convenient subdifferential \cite[Proposition 8.7]{vari_ana}.} 
	\begin{align}\label{crit_want}
	\mathbf{x}(k) \to \mathbf{x}^*, ~ F(\mathbf{x}(k)) \to F(\mathbf{x}^*), ~ \mathbf{0} \leftarrow \mathbf{u}(k) \in \partial F(\mathbf{x}(k)).
	\end{align} 

	Let us first construct the subgradient sequence $\mathbf{u}(k)$. Consider machine $i$ and any $\hat t \in T_i$, the optimality condition of \cref{update_exp} gives
	\begin{flalign}
	u_i( \hat t+1) := -\tfrac{1}{\eta} \left[x_i(\hat t+1) - x_i(\hat t) + \eta \nabla_{i} f\big(\mathbf{x}^i(\hat t)\big)\right] \in \partial g_i(x_i( \hat t+1)).
	\end{flalign}
	It then follows that 
	\begin{flalign}
	\|u_i( \hat t+1) & + \nabla_i f(\mathbf{x}( \hat t+1))\| \nonumber\\
	&\leq 
	\|u_i( \hat t+1) + \nabla_i f(\mathbf{x}( \hat t ))\| + \|\nabla_i f(\mathbf{x}( \hat t+1)) - \nabla_i f(\mathbf{x}(\hat t))\|
	\nonumber\\
	&\overset{\mathrm{(i)}}{\le} 
	\left\| \tfrac{1}{\eta} \left[ x_i( \hat t+1) - x_i(\hat t) \right] + \nabla_{i} f\big(\mathbf{x}^{i}(\hat t)\big) - \nabla_{i} f\big(\mathbf{x}(\hat t)\big) \right\| + L\|\mathbf{x}(\hat t+1) - \mathbf{x}(\hat t)\|
	\nonumber\\
	&\overset{\mathrm{(ii)}}{\le} 
	\tfrac{1}{\eta} \| x_i(\hat t+1) - x_i(\hat t) \| + L \|\mathbf{x}^{i}(\hat t) - \mathbf{x}(\hat t)\| + L \|\mathbf{x}(\hat t+1) - \mathbf{x}(\hat t)\|
	\nonumber\\
	\label{sub_zero_1}
	&\overset{\mathrm{(iii)}}{\le}
	\tfrac{1}{\eta} \| x_i(\hat t+1) - x_i(\hat t) \| + L \sum_{k=(\hat t-s)_+}^{\hat t} \|\mathbf{x}(k+1) - \mathbf{x}(k)\|,
	\end{flalign}
	where (i) and (ii) are due to the $L$-Lipschitz continuity of $\nabla f$, and (iii) follows from \cref{incon_bound}.
	Next, consider any other $t\not\in T_i$ and $t\geq s$, we denote $\hat t$ as the \emph{largest} element in the set $\{ k \leq t: k \in T_i \}$. By \Cref{assum:skip} $\hat t$ always exists and $t - \hat t\leq s$. Since no update is performed on machine $i$ at any clock in $[\hat{t}+1, t]$, we have $x_i(t+1) = x_i(\hat t + 1)$. Thus, we can choose $u_i(t+1) = u_i(\hat t+1) \in \partial g_i (x_i(\hat{t}+1)) = \partial g_i (x_i(t+1))$, and obtain
	\begin{align}
	\| u_i(t+1) + \nabla_i f(\mathbf{x}(t+1)) - & u_i(\hat t + 1) - \nabla_i f(\mathbf{x}(\hat t + 1)) \|  \\
	&= 
	\| \nabla_i f(\mathbf{x}(t+1)) - \nabla_i f(\mathbf{x}(\hat t + 1)) \|
	\nonumber\\
    &\leq
	\sum_{k = \hat t
		+1}^t \|\nabla_i f(\mathbf{x}(k+1)) - \nabla_i f(\mathbf{x}(k))\|
	\nonumber\\
	&\leq 
	\sum_{k = (t-s+1)_+}^{ t} \|\nabla_i f(\mathbf{x}(k+1)) - \nabla_i f(\mathbf{x}(k))\|
	\nonumber\\
	\label{sub_zero_2}
	&{\le}
	\sum_{k = (t-s+1)_+}^{t} L \|\mathbf{x}(k+1) - \mathbf{x}(k)\|.
	\end{align}
	Combining the two cases in \cref{sub_zero_1} and \cref{sub_zero_2} we have for all $t$:
	\begin{align}
	\label{subdiff_bound}
	\| \mathbf{u}(t+1) + \nabla f(\mathbf{x}(t+1))\| 
	\leq 
	(\sqrt{p}/\eta + 2L) {\sum_{k = (t-2s)_+}^t} \| \mathbf{x}(k+1) - \mathbf{x}(k) \|,
	\end{align}
	where $\mathbf{u}(t+1) = \big( u_1(t+1),~ \ldots~,~ u_p(t+1) \big) \in \partial g (\mathbf{x}(t+1))$, and the factor $\sqrt{p} \geq 1$ is artificially introduced for the convenience of subsequent analysis. Therefore, by \cref{subdiff_bound} and \Cref{thm:limitcon} we deduce
	\begin{align}
	\label{crit_1}
	\lim_{t\to\infty} \mathrm{dist}_{\partial F(\mathbf{x}(t+1))}(\mathbf{0}) \leq  \lim_{t\to\infty } 	\| \mathbf{u}(t+1) + \nabla f(\mathbf{x}(t+1))\| = 0.
	\end{align}

	Recall that $\mathbf{x}^*$ is a limit point of $\{\mathbf{x}(t)\}$, thus there exists a  subsequence $\mathbf{x}(t_m) \to \mathbf{x}^*$. Next we verify the function value convergence in \cref{crit_want}. 
	The challenge here is that the component function $g$ is only closed, hence may not be continuous. 
	For any $t \in T_i$, applying \cref{usc} with $z = x_i^*$ and rearranging gives 
	\begin{align}
	g_i(x_i(t + 1)) 
	&\le 
	g_i\big(x^*_i\big) + \frac{1}{2\eta}\|x_i^* - x_i(t)\|^2  - \frac{1}{2\eta}\|x_i(t+1) - x_i(t)\|^2  \nonumber\\
	&\quad + \inner{x_i^* - x_i(t+1)}{\nabla_i f(\mathbf{x}^i(t))}  \nonumber\\
	\label{uniform}
	&= 
	g_i\big(x^*_i\big) + \frac{1}{2\eta}\|x_i^* - x_i(t)\|^2  - \frac{1}{2\eta}\|x_i(t+1) - x_i(t)\|^2  
	\\
	& \quad + \inner{x_i^* - x_i(t+1)}{\nabla_i f(\mathbf{x}^*)} + \inner{x_i^* - x_i(t+1)}{\nabla_i f(\mathbf{x}^i(t)) - \nabla_i f(\mathbf{x}^*)}.
	\nonumber
	\end{align}
	 Observe from \Cref{thm:limitcon} that 
	\begin{align*}
	\lim_{m\to\infty} \max_{t \in [t_m-s, t_m + s]} \|\mathbf{x}(t+1) - \mathbf{x}^*\| = 0, \qquad \lim_{m\to\infty} \max_{t \in [t_m-s, t_m + s]} \|\mathbf{x}^i(t+1) - \mathbf{x}^*\| = 0.
	\end{align*}
	By \Cref{assum:skip}, $[t_m -s, t_m + s] \cap T_i \ne \emptyset$ for all $i$. Then using the Lipschitz continuity of $\nabla f$ we deduce from \cref{uniform} that
	\begin{align}
	\label{eq:func_con}
	\limsup_{m \to \infty} \max_{t\in[t_m-s, t_m+s] \cap T_i} g_i(x_i(t+1)) \leq g_i(x_i^*).
	\end{align}
