	Also notice that each machine $i$ only updates at its active clocks $T_i$, it then follows that
	\begin{align*}
	\max_{t\in[t_m, t_m+s]} g_i(x_i(t+1)) = \max_{t\in[\hat t_m, t_m+s] \cap T_i} g_i(x_i(t+1)) \leq \max_{t\in[t_m -s, t_m+s] \cap T_i} g_i(x_i(t+1)),
	\end{align*}
	and hence by \eqref{eq:func_con}
	\begin{align}\label{eq: usc}
	\limsup_{m \to \infty} \max_{t\in[t_m, t_m+s]} g_i(x_i(t+1)) \leq  g_i(x_i^*).
	\end{align}

	To complete the proof, choose any $k_m\in [t_m, t_m+s]$. Since $\mathbf{x}(t_m) \to \mathbf{x}^*$, \Cref{thm:limitcon} implies that

\begin{remark}
Our bound on the step size $\eta$ is natural: If $s = 0$, {i.e.}\xspace, there is no asynchronism then we recover the standard step size rule $\eta < 1/L$ (we can increase $\eta$ by another factor of 2, had convexity on $g$ been assumed). As staleness $s$ increases, we need a smaller step size to ``damp'' the system to still ensure convergence. The factor $\sqrt{p}$ is another measurement of the degree of ``dependency'' among worker machines: Indeed, we can reduce $\sqrt{p}$ to $\sqrt{\sum_i L_i^2} / L$, where $L_i$ is the Lipschitz constant of $\nabla_i f$ ({cf.}\xspace \eqref{eq:Lip}). 
\end{remark}
\begin{proof} 
	The last claim follows immediately from \cref{sq_summable} and \cref{incon_bound}, so we only need to prove \eqref{sq_summable}.

	Consider machine $i$ and any $t\in T_i$. Combining \cref{update_op} with \cref{mspg_formulation} gives  
	\begin{align}\label{update_exp}
	x_i(t+1) = \prox{g_i}\big(x_i(t) - \eta \nabla_i f(\mathbf{x}^i(t))\big).
	\end{align}
	Then, from \Cref{def:prox_map} of the proximal map we have for all $z\in\mathds{R}^{d_i}$:
	\begin{flalign}\label{usc}
	g_i\big(x_i(t+1)\big) + \frac{1}{2\eta}\|x_i(t+1) &- x_i(t) + \eta\nabla_{i} f\big(\mathbf{x}^i(t)\big)\|^2 \\
	&\le 
	g_i\big(z\big) + \frac{1}{2\eta}\left\|z - x_i(t) + \eta \nabla_{i} f\big(\mathbf{x}^i(t)\big)\right\|^2. \nonumber
	\end{flalign}
	Set $z = x_i(t)$ and simplify, we obtain:
	\begin{flalign}
	\label{prog_g}
	g_i\big(x_i(t+1)\big) - &g_i\big(x_i(t)\big)  \\
	&\le 
	- \frac{1}{2\eta}\|x_i(t+1) - x_i(t)\|^2 -\left\langle \nabla_{i} f\big(\mathbf{x}^i(t)\big),  x_i(t+1) - x_i(t) \right\rangle. \nonumber
	\end{flalign}
	Note that if $t \notin T_i$, then $x_i(t+1) = x_i(t)$ and \cref{prog_g} still holds. 
	On the other hand, \Cref{assum:smooth} implies that for all $t$ ({cf.}\xspace \eqref{eq:qb}):
	\begin{flalign}\label{prog_f}
	f\big(\mathbf{x}(t+1)\big) - f\big(\mathbf{x}(t)\big) 
	\le 
	\langle \mathbf{x}(t+1)-\mathbf{x}(t), \nabla f\big(\mathbf{x}(t)\big) \rangle + \frac{L}{2} \|\mathbf{x}(t+1)-\mathbf{x}(t)\|^2.
	\end{flalign}
	Adding up \cref{prog_f} and \cref{prog_g} (for all $i$) and recall $F = f+ \sum_i g_i$, we have
	\begin{flalign}
	F\big(\mathbf{x}(t+1)\big) - F\big(\mathbf{x}(t)\big) & - \tfrac{1}{2}(L - 1/\eta) \|\mathbf{x}(t+1) - \mathbf{x}(t)\|^2 \nonumber\\
	&\le 
	 \sum_{i=1}^{p} \left\langle x_i(t+1)-x_i(t), \nabla_i f(\mathbf{x}(t)) -  \nabla_{i} f\big(\mathbf{x}^{i}(t)\big)\right\rangle
	\nonumber\\

	&\le 
	 \sum_{i=1}^{p} \|x_i(t+1)-x_i(t)\| \cdot \|\nabla_i f(\mathbf{x}(t)) -  \nabla_{i} f\big(\mathbf{x}^{i}(t)\big) \|
	\nonumber\\
	&\overset{\mathrm{(i)}}{\le} 
	 \sum_{i=1}^{p} \|x_i(t+1)-x_i(t)\| \cdot L \|\mathbf{x}(t) - \mathbf{x}^{i}(t) \|
	\label{eq:Lip}\\
	&\overset{\mathrm{(ii)}}{\le} 
	 L \cdot \sum_{i=1}^{p} \|x_i(t+1)-x_i(t)\| \cdot  \sum_{k=(t-s)_+}^{t-1} \|\mathbf{x}(k+1) - \mathbf{x}(k) \|
	\nonumber\\
	&\overset{\mathrm{(iii)}}{\le}  
	\sqrt{p} L \|\mathbf{x}(t+1)-\mathbf{x}(t)\| \cdot  \sum_{k=(t-s)_+}^{t-1} \|\mathbf{x}(k+1) - \mathbf{x}(k) \| \label{eq: func_moment}
	\\
	&\overset{\mathrm{(iv)}}{\le} 
	 \frac{\sqrt{p} L}{2}\sum_{k=(t-s)_+}^{t-1} \Big[\|\mathbf{x}(k+1) - \mathbf{x}(k) \|^2 + \|\mathbf{x}(t+1)-\mathbf{x}(t)\|^2 \Big]
	\nonumber\\
	&\le  \label{eq: progress}
	\frac{\sqrt{p} L s}{2} \|\mathbf{x}(t+1) \!-\! \mathbf{x}(t)\|^2 + \frac{\sqrt{p} L}{2} \!\sum_{k=(t-s)_+}^{t-1} \!\!\!\|\mathbf{x}(k+1) \!-\! \mathbf{x}(k) \|^2,
	\end{flalign}
	where (i) is due to the $L$-Lipschitz continuity of $\nabla f$, (ii) follows from \cref{incon_bound}, (iii) is the Cauchy-Schwarz inequality, and (iv) follows from the elementary inequality $ab\leq \tfrac{a^2+b^2}{2}$.
	Summing the above inequality over $t$ from $0$ to $n-1$ and rearranging we obtain
	\begin{flalign*}
	F\big(\mathbf{x}(n)\big) - F\big(\mathbf{x}(0)\big) 
	& \leq
	\frac{1}{2}(L + \sqrt{p} Ls - 1/\eta) \sum_{t=0}^{n-1} \|\mathbf{x}(t+1) - \mathbf{x}(t)\|^2 \\
	&\quad+ \frac{L}{2} \sum_{t=0}^{n-1} \sum_{k=(t-s)_+}^{t-1} \|\mathbf{x}(k+1) - \mathbf{x}(k) \|^2
	\\
	&\leq
	\frac{1}{2}(L + 2\sqrt{p}Ls - 1/\eta)  \sum_{t=0}^{n-1} \|\mathbf{x}(t+1) - \mathbf{x}(t)\|^2.
	\end{flalign*}
	Therefore, if we choose $0 < \eta < \frac{1}{L (1 + 2\sqrt{p}s)}$, then let $n\rightarrow \infty$ we deduce
	\begin{align}
	\sum_{t=0}^{\infty} \|\mathbf{x}(t+1) - \mathbf{x}(t)\|^2 
	\leq 
	\frac{2}{1/\eta - L - 2\sqrt{p}Ls} [F\big(\mathbf{x}(0)\big) - \inf_{\mathbf{z}} F(\mathbf{z})].
	\end{align}
	By \Cref{assum:bb}, $F$ is bounded from below, hence the right-hand side is finite. 
\end{proof}

The first assertion of the above theorem states that the global sequence $\mathbf{x}(t)$ has square summable successive differences, while the second assertion implies that both the successive difference of the global sequence and the inconsistency between the local sequences and the global sequence diminish as the number of iterations grows. These two conclusions provide a prelimenary stability guarantee for \textsf{m-PAPG}\xspace. 

Next, we prove that the limit points (if exist) of the sequences $\mathbf{x}(t)$ and $\mathbf{x}^i(t), i=1,\ldots, p$ coincide, and they are critical points of $F$. Again, no convexity assumption is imposed on either $f$ or $g$.

\begin{proof}
	The first inequality is obtained by summing the inequality \cref{eq: progress} over $t, t+1, \cdots, t+s$. So we need only prove the second inequality. 

	Let us introduce some notations to simplify the proof.
	For each machine $i$ let $t_i$  be the largest clock in $[t, t+s] \cap T_i$, and denote
	\begin{align}
	\label{eq:z}
	\mathbf{z} &= \big(x_1(t_1), ~\ldots~, x_p(t_p)\big) \\
	\label{eq:z2} \mathbf{z}^+ &= \big(x_1(t_1+1), ~\ldots~, x_p(t_p+1)\big) = \big(x_1(t+s+1), ~\ldots~, x_p(t+s+1)\big),
	\end{align}
	where the last equality is due to the maximality of each $t_i$.
	From the optimality condition of the proximal map $z^+_i = \prox{g_i}(z_i - \eta \nabla_i f(\mathbf{x}^i(t_i)))$ we deduce
	\begin{align}
	\label{eq:subgrad}
	\eta^{-1} (z_i - z_i^+) - \nabla_i f(\mathbf{x}^i (t_i)) \in \partial g_i (z_i^+).
	\end{align}
	Since the gradient of $f$ is $L$-Lipschitz continuous and the function $g$ is convex, we obtain
	\begin{align*}
	f(\mathbf{z}^+) - f(\bar\mathbf{z}) &\le \sum_{i=1}^p \langle z^+_i -  \bar z_i, \nabla_i f(\bar\mathbf{z})\rangle + \frac{L}{2} \|\mathbf{z}^+ - \bar\mathbf{z}\|^2, \\
	g(\mathbf{z}^+) - g(\bar\mathbf{z}) &\le \sum_{i=1}^p \langle z^+_i -  \bar z_i, \eta^{-1} (z_i - z_i^+) - \nabla_i f(\mathbf{x}^i (t_i)) \rangle,
	\end{align*}
	where we define $\bar \mathbf{z} := \proj{\mathop{\mathrm{crit}} F}(\mathbf{z})$, {i.e.}\xspace, the projection of $\mathbf{z}$ onto the set of critical points of $F$, and the last inequality follows from \cref{eq:subgrad}.

	Adding up the above two inequalities we obtain
	\begin{align*}
	F(&\mathbf{z}^+) - F^* - \tfrac{L}{2} \|\mathbf{z}^+ - \bar\mathbf{z}\|^2 \le \sum_{i=1}^p \langle z^+_i -  \bar z_i, \nabla_i f(\bar\mathbf{z}) + \eta^{-1} (z_i - z_i^+) - \nabla_i f(\mathbf{x}^i (t_i))\rangle \\
	&\overset{\mathrm{(i)}}{\le} \sum_{i=1}^{p} [\|z_i^+ - z_i\| + \|z_i - \bar z_i\|] [\|\nabla_i f(\mathbf{x}^i (t_i)) - \nabla_i f(\bar\mathbf{z})\| + \eta^{-1} \|z_i - z_i^+\|] \\	
	&\overset{\mathrm{(ii)}}{\le} \sum_{i=1}^{p} 4\left[ \|z_i^+ - z_i\|^2 + \|z_i - \bar z_i\|^2 + \eta^{-2} \|z_i^+ - z_i\|^2 + \|\nabla_i f(\mathbf{x}^i (t_i)) - \nabla_i f(\bar\mathbf{z})\|^2 \right] \\
	&\le 4\left[ \|\bar\mathbf{z} - \mathbf{z}\|^2 + (1+\eta^{-2}) \|\mathbf{z}^+ - \mathbf{z}\|^2 +  \sum_{i=1}^{p} L^2 \|\mathbf{x}^i (t_i) - \bar\mathbf{z}\|^2 \right],
	\end{align*}
	where (i) is due to the Cauchy-Schwarz inequality and the triangle inequality, (ii) is due to the elementary inequality $(a+b)(c+d) \leq 4(a^2+b^2+c^2+d^2)$, and the last inequality is due to the $L$-Lipschitz continuity of $\nabla f$.

	Using again the triangle inequality we obtain from the above inequality that
	\begin{align}
	F(\mathbf{z}^+) - F^* &\le (L+4)\|\bar\mathbf{z} - \mathbf{z}\|^2 + (L+4+\tfrac{4}{\eta^{2}}) \|\mathbf{z}^+ - \mathbf{z}\|^2 + 4L^2\sum_{i=1}^{p} \|\mathbf{x}^i (t_i) - \mathbf{z}\|^2 \nonumber\\
	\nonumber&\overset{\mathrm{(i)}}{=} (L\!+\!4)\|\bar\mathbf{z} \!-\! \mathbf{z}\|^2 \!+\! \sum_{i=1}^{p} [(L\!+\!4\!+\!\tfrac{4}{\eta^{2}})\|x_i(t_i\!+\!1) \!-\! x_i(t_i)\|^2 \!+\! 4L^2\|\mathbf{x}^i (t_i) \!-\! \mathbf{z}\|^2],\\
	&\overset{\mathrm{(ii)}}{\leq} (L\!+\!4)\|\bar\mathbf{z} \!-\! \mathbf{z}\|^2 + (L\!+\!4\!+\!\tfrac{4}{\eta^{2}}) B(t+s+1) + 4L^2\sum_{i=1}^{p}  \|\mathbf{x}^i (t_i) \!-\! \mathbf{z}\|^2,	
	\label{eq:Fgap}
	\end{align}
	where (i) is due to our definition of $\mathbf{z}$ and $\mathbf{z}^+$ in \eqref{eq:z} and \eqref{eq:z2}, and (ii) is due to the fact that $t_i \in [t, t+s]$ for all $i$.

	We next bound the terms $\|\bar\mathbf{z} - \mathbf{z}\|^2$ and $\|\mathbf{x}^i (t_i) \!-\! \mathbf{z}\|^2$. First, note that

	\begin{align*}
	\| x_i(t_i+1) - x_i(t_i)\| &= \|\prox{g_i}(x_i(t_i) - \eta \nabla_i f(\mathbf{x}^i (t_i))) - x_i(t_i)\| \\
	&\ge \|\prox{g_i}(x_i(t_i) - \eta \nabla_i f(\mathbf{z})) - x_i(t_i)\| \\
	&\quad - \|\prox{g_i}(x_i(t_i) - \eta \nabla_i f(\mathbf{x}^i (t_i))) - \prox{g_i}(x_i(t_i) - \eta \nabla_i f(\mathbf{z})) \| \\
	&\overset{\mathrm{(i)}}{\ge} \|\prox{g_i}(x_i(t_i) - \eta \nabla_i f(\mathbf{z})) - x_i(t_i)\| - \eta L \|\mathbf{z} - \mathbf{x}^i(t_i)\|,
	\end{align*}
	where (i) follows from the non-expansiveness of $\prox{g}$ (recall that $g$ is convex) and the $L$-Lipschitz continuity of $\nabla f$.
	Rearranging the above inequality and summing over all $i$, we obtain
	\begin{align}
	\nonumber \|\prox{g}(\mathbf{z}- \eta \nabla f(\mathbf{z})) - \mathbf{z}\|^2 &\le \sum_{i=1}^p \left[\| x_i(t_i+1) - x_i(t_i)\| +  \eta L \|\mathbf{z} - \mathbf{x}^i(t_i)\| \right]^2 \\
	\label{eq:proxb}&\le 2\sum_{i=1}^p \left[\| x_i(t_i+1) - x_i(t_i)\||^2 +  \eta^2 L^2 \|\mathbf{z} - \mathbf{x}^i(t_i)\|^2 \right]. 


	\end{align}
	The last term $\|\mathbf{z} - \mathbf{x}^i(t_i)\|^2$ can be further bounded as follows:  
	\begin{align}
	\nonumber
	\|\mathbf{z} - \mathbf{x}^i(t_i)\|^2 &= \sum_{j=1}^p \|x_j(t_j) - x_j (\tau_j^i (t_i))\|^2 \\
	&= \sum_{j=1}^p \Big\|\sum_{k = \min\{ t_j, \tau_j^i(t_i) \} }^{\max\{ t_j, \tau_j^i(t_i) \}-1} x_j(k+1) - x_j(k) \Big\|^2 \nonumber\\
	&\le \sum_{j=1}^p \Big[\sum_{k = \min\{ t_j, \tau_j^i(t_i) \} }^{\max\{ t_j, \tau_j^i(t_i) \}-1} \| x_j(k+1) - x_j(k) \| \Big]^2 \nonumber\\	
	&\overset{\mathrm{(i)}}{\le} \sum_{j=1}^p 2s \sum_{k= t-s}^{t+s-1} \| x_j(k+1) - x_j(k) \|^2 \nonumber\\

	\nonumber &= 2s \sum_{k=t-s}^{t+s-1} \|\mathbf{x}(k+1) - \mathbf{x}(k)\|^2 \\
	\label{eq:diff} & \leq 2s [B(t) + B(t+s+1)],
	\end{align}
	where (i) is due to the fact that $t_j \in [t, t+s]$ and $\tau_j^i(t_i) \in [t-s, t+s]$.
	Combining \eqref{eq:proxb} and \eqref{eq:diff} we obtain
	\begin{align}
	\label{eq:pb} \|\prox{g}(\mathbf{z} - \eta \nabla f(\mathbf{z})) &- \mathbf{z}\|^2 
	\leq 2 B(t+s+1) +  4ps\eta^2 L^2 [B(t) + B(t+s+1)].

	\end{align}

	Thanks to \Cref{thm:limitcon}, we know for $t$ sufficiently large, $\|\prox{g}(\mathbf{z} \!-\! \eta \nabla f(\mathbf{z})) \!-\! \mathbf{z}\| \leq \eta\delta$. Since the function $\eta \mapsto \frac{1}{\eta}\|\prox{g}(\mathbf{z} \!-\! \eta \nabla f(\mathbf{z})) \!-\! \mathbf{z}\|$ is monotonically decreasing \cite{Sra12}, we can apply the error bound condition in \Cref{assum:eb} for $\eta < 1$ and $t$ sufficiently large, and obtain
	\begin{align}
	\label{eq:projdist}
	\|\bar\mathbf{z} - \mathbf{z}\|^2 \le \kappa \|\mathbf{z} - \prox[]{g}(\mathbf{z} - \nabla f(\mathbf{z}))\|^2 \le \kappa \eta^{-2} \|\mathbf{z} - \prox{g}(\mathbf{z} - \eta\nabla f(\mathbf{z}))\|^2.
	\end{align}













	Finally, combining \eqref{eq:Fgap}, \eqref{eq:diff}, \eqref{eq:pb} and \eqref{eq:projdist} we arrive at:
	\begin{align}
	\nonumber
	F(\mathbf{x}(t\!+\!s\!+\!1)) - F^* &= F(\mathbf{z}^+) - F^* \\
	\nonumber&\le (L\!+\!4)\|\bar\mathbf{z} \!-\! \mathbf{z}\|^2 + (L\!+\!4\!+\!\tfrac{4}{\eta^{2}}) B(t\!+\!s\!+\!1) + 4L^2\sum_{i=1}^{p}  \|\mathbf{x}^i (t_i) \!-\! \mathbf{z}\|^2,\\	

	&\le  a_\eta B(t+s+1) +  b B(t),
	\end{align}
	where the coefficients are
	\begin{align}
	\label{eq:ab}
	a_\eta &= L+4+8psL^2 + 4ps\kappa L^2(L+4) + \tfrac{2}{\eta^2}(2+4\kappa+\kappa L), \\
	b &= 8psL^2+4ps\kappa L^2(L+4).
	\end{align}

















































































\end{proof}

\Cref{lemma: EB_2} improves the analysis of \cite{Tseng_linear_PAA} in three aspects: (1) it is shorter and simpler; (2) it allows any convex function $g$; and (3) the leading coefficient for $B(t)$ is reduced from $O(1/\eta)$ to $O(1)$. 
The two recursive relations in Lemma \ref{lemma: EB_2}, as shown in \cite[Lemma 4.5]{Tseng_linear_PAA}, easily imply the following convergence guarantee:

\begin{proof}



















Using the elementary inequality $\|a\|^2 - \|b\|^2 \le 2\|a\|\|a - b\|$, we have for all $t$:
\begin{flalign}
\|\mathbf{x}(t+1) - &\mathbf{x}(t)\|^2 - \left\|\mathbf{x}(t+2) - \mathbf{x}(t+1)\right\|^2 \nonumber\\
&\le 2\left\|\mathbf{x}(t+1) - \mathbf{x}(t)\right\| \cdot \left\|(\mathbf{x}(t+1) - \mathbf{x}(t)) - (\mathbf{x}(t+2) - \mathbf{x}(t+1))\right\|
 \nonumber\\
 &\leq  2\left\|\mathbf{x}(t+1) - \mathbf{x}(t)\right\| \cdot \sum_{i=1}^{p}\left\|(x_i(t+1) - x_i(t)) - (x_i(t+2) - x_i(t+1))\right\|\nonumber\\
&\ovset{(i)}{\leq}  2\left\|\mathbf{x}(t+1) - \mathbf{x}(t)\right\| \cdot \sum_{i=1}^{p} \left \|\Delta_\eta(\mathbf{x}^{i} (t)) - \Delta_\eta(\mathbf{x}^{i} (t+1))\right\|\nonumber\\

&\ovset{(ii)}{\le} 2\left\|\mathbf{x}(t+1) - \mathbf{x}(t)\right\| \left(\sum_{i=1}^{p} L_\eta \|\mathbf{x}^{i} (t) - \mathbf{x}^{i} (t+1)\| \right)\nonumber\\
&\ovset{(iii)}{\le}  2pL_\eta \left\|\mathbf{x}(t+1) - \mathbf{x}(t)\right\|  \cdot \sum_{k=(t-s)_+}^{t}\|\mathbf{x}(k+1) - \mathbf{x}(k)\|,  \label{eq:induction}


\end{flalign}
where (i) is due to \Cref{assum:always} hence $t\in T_i$ for all $t$, (ii) follows from \Cref{assum:EL}, and (iii) is due to \eqref{eq:local_diff}.

If for some $r > 1$ there exists some $T$ such that for all $t \geq T$,
\begin{align}
\label{eq:case}
\sum_{k=( t-s)_+}^{ t}\|\mathbf{x}(k+1) - \mathbf{x}(k)\| \ge C \|\mathbf{x}(t+1) - \mathbf{x}(t)\|,
\end{align}
where $C=\frac{r^{s+1}-1}{r-1} > s+1$ (since $r > 1$ and w.l.o.g. $s > 0$). Summing the index $t$ from $T$ to $n$ yields
\begin{flalign}
C\sum_{t= T}^{n}\left\|\mathbf{x}(t+1) - \mathbf{x}(t)\right\| &\leq \sum_{t=T}^{n}\sum_{k=(t-s)_+}^{t}\left\|\mathbf{x}(k+1) - \mathbf{x}(k)\right\|\nonumber\\
&\leq (s+1)\sum_{t=(T-s)_+}^{n}\left\|\mathbf{x}(t+1) - \mathbf{x}(t)\right\|,\nonumber
\end{flalign}
which after rearranging terms becomes
\begin{flalign}
(C -  s - 1)\sum_{t= T}^{n}\left\|\mathbf{x}(t+1) - \mathbf{x}(t)\right\| \leq (s+1)\sum_{t=(T-s)_+}^{T-1}\left\|\mathbf{x}(t+1) - \mathbf{x}(t)\right\|. \nonumber
\end{flalign}
Since the right hand side does not depend on $n$, letting $n$ tend to infinity we conclude
\begin{flalign}\label{eq: case2}
\sum_{t=0}^{\infty}\|\mathbf{x}(t+1) - \mathbf{x}(t)\|< \infty,
\end{flalign}
and the proof of the finite length property would be complete.



Therefore, in the remaining part of the proof, we can assume \eqref{eq:case} fails for infinitely many $t$. Take any such $t=\hat t$, we have 
\begin{align}
\label{eq:induction2}
\sum_{k=( t-s)_+}^{ t}\|\mathbf{x}(k+1) - \mathbf{x}(k)\| \leq C \|\mathbf{x}(t+1) - \mathbf{x}(t)\| \leq C^2 \|\mathbf{x}(t+1) - \mathbf{x}(t)\|,
\end{align}
since $C > 1$. 
Combining \eqref{eq:induction} and \eqref{eq:induction2} we have for $t=\hat t$:
\begin{flalign}
\left\|\mathbf{x}(t+1) - \mathbf{x}(t)\right\|^2 - \left\|\mathbf{x}(t+2) - \mathbf{x}(t+1)\right\|^2 

&\le 2pL_\eta C^2 \left\|\mathbf{x}(t+1) - \mathbf{x}(t)\right\|^2 \nonumber\\
&\leq \left(1-\frac{1}{r^2} \right) \left\|\mathbf{x}(t+1) - \mathbf{x}(t)\right\|^2,\nonumber
\end{flalign}
if $\eta$ is small enough (recall that $L_\eta = o(1)$).
After rearranging terms we conclude that for $t=\hat t$:
\begin{align}
\label{eq:ind}
\|\mathbf{x}(t+1) - \mathbf{x}(t)\| \le r\|\mathbf{x}(t+2) - \mathbf{x}(t+1)\|.
\end{align}
Using induction we can continue the same process for any $t \geq \hat t$. Indeed, suppose \eqref{eq:ind} is true for any $t \leq m-1$, then \eqref{eq:induction} holds (for any $t$), and \eqref{eq:induction2} also holds: If $m \leq \hat t + s$, then
\begin{align*}
\sum_{k=(m-s)_+}^{m}\!\!\! \|\mathbf{x}(k\!+\!1) \!-\! \mathbf{x}(k)\| 
&=
\sum_{k=(m-s)_+}^{\hat t}\|\mathbf{x}(k+1) - \mathbf{x}(k)\| + \sum_{k=\hat t+1}^{m}\|\mathbf{x}(k+1) - \mathbf{x}(k)\| 
\\
&\ovset{(i)}{\leq} 
\sum_{k=(\hat t-s)_+}^{\hat t} \!\! \|\mathbf{x}(k\!+\!1) \!-\! \mathbf{x}(k)\| + \sum_{k=\hat t+1}^{m} \!\!r^{m-k} \|\mathbf{x}(m\!+\!1) \!-\! \mathbf{x}(m)\| 
\\
&\ovset{(ii)}{\leq}  
C\left[\|\mathbf{x}(\hat t+1) - \mathbf{x}(\hat t)\| + \sum_{k=\hat t+1}^{m} r^{m-k} \|\mathbf{x}(m+1) - \mathbf{x}(m)\|\right] 
\\
&\ovset{(iii)}{\leq} 
C \sum_{k=\hat t}^{m} r^{m-k} \|\mathbf{x}(m+1) - \mathbf{x}(m)\| \\
&\ovset{(iv)}{\leq} 
C^2 \|\mathbf{x}(m+1) - \mathbf{x}(m)\|,
\end{align*}
where (i) is due to the induction hypothesis, (ii) is due to the definition of $\hat t$ and the fact that $C>1$, (iii) is due to again the induction hypothesis, and finally (iv) is due to the definition of $C$ (recall $m\leq \hat t +s$). If $m > \hat t + s$, the same inequality, with $C^2$ replaced by $C$, would still hold (essentially dropping all the first terms on the right hand side of the above inequalities). Thus, \eqref{eq:induction} and \eqref{eq:induction2} would imply again \eqref{eq:ind} for $t = m$.

Lastly, we recall from \cref{eq: func_moment} that for large $t$, 
\begin{flalign}
F\big(\mathbf{x}(t+1)\big) - F\big(\mathbf{x}(t)\big) 
&\le 
\tfrac{1}{2}(L - 1/\eta) \|\mathbf{x}(t+1) - \mathbf{x}(t)\|^2 \nonumber\\
&\quad+ \sqrt{p}L\|\mathbf{x}(t+1)-\mathbf{x}(t)\| \sum_{k=(t-s)_+}^{t-1} \|\mathbf{x}(k+1) - \mathbf{x}(k) \|. \nonumber
\\
&\leq
\tfrac{1}{2}(L - 1/\eta) \|\mathbf{x}(t+1) - \mathbf{x}(t)\|^2  + \sqrt{p}CL\|\mathbf{x}(t+1)-\mathbf{x}(t)\|^2. \nonumber
\\
&\leq
-\alpha \|\mathbf{x}(t+1) - \mathbf{x}(t)\|^2, \nonumber
\end{flalign}
where $\alpha = \tfrac{1}{2}(1/\eta - L - 2\sqrt{p}CL) > 0$ if $\eta$ is small. Hence, the sufficient decrease property in \Cref{assum:sd} is verified and the finite length properties follow from \Cref{thm:finite}.
\end{proof}































Lastly, we show that \Cref{assum:EL} also holds for the important cardinality function $\|\mathbf{x}\|_0$ (number of nonzero entries).

\begin{proof}

















The crucial observation here is that for the cardinality function $g = \|\cdot\|_0$, its proximal map on the $j$-th entry can be chosen as:
\begin{flalign}
\label{eq:prox_l0}
\mathrm{prox}_{g_j}^{\eta}(z_j) =  
\left\{ \begin{array}{l}
z_j, ~\text{if $|z_j|>\sqrt{2\eta}$}\\
0, ~\text{otherwise}
\end{array} \right.
.
\end{flalign}


However, \Cref{thm:limitcon} implies that $\lim\limits_{t\to\infty} \|\mathbf{x}^i(t+1) - \mathbf{x}^i(t)\| = 0$. Thus, for $t$ sufficiently large, the sequence $\{\mathbf{x}^i(t)\}$ will have the same support $\Omega$ (indices that have nonzero entries), for otherwise $\|\mathbf{x}^i(t+1) - \mathbf{x}^i(t)\| \geq \sqrt{2\eta}$ even if one index in the support changes.




Therefore,
\begin{align*}
\|\Delta_\eta(\mathbf{x}^i(t+1)) - \Delta_\eta(\mathbf{x}^i(t))\| 
&\ovset{(i)}{\leq}
\sum_{j\in \Omega}\|\prox{g_j}(x_j^i(t+1) - \eta \nabla_j f(\mathbf{x}^i(t+1))) - x_j^i(t+1)\nonumber\\
&\qquad\qquad\qquad - \prox{g_j}(x_j^i(t) - \eta \nabla_j f(\mathbf{x}^i(t))) - x_j^i(t)\|
\\
&\ovset{(ii)}{\leq}
\sum_{j\in \Omega} \|\eta \nabla_j f(\mathbf{x}^i(t+1)) - \eta \nabla_j f(\mathbf{x}^i(t)) \|
\\
&\ovset{(iii)}{\leq}
\eta p L \|\mathbf{x}^i(t+1) - \mathbf{x}^i(t)\|,
\end{align*}
where (i) is the triangle inequality, (ii) uses the property of the proximal map \eqref{eq:prox_l0}, and (iii) is due to \Cref{assum:smooth}.
























\end{proof}

Note that similar results as \Cref{thm:example} can be derived for the rank function, and more generally for functions whose proximal map is discontinuous with pieces satisfying \Cref{thm:lcg}.
